:root {
  --bg-1: #07131d;
  --bg-2: #112536;
  --panel: rgba(11, 18, 27, 0.72);
  --panel-strong: rgba(11, 18, 27, 0.94);
  --board: #132c3e;
  --board-edge: #1d425d;
  --text: #edf6ff;
  --muted: #9bb4c8;
  --accent: #7bdcb5;
  --accent-2: #5cc7ff;
  --accent-3: #f7d66b;
  --danger: #ef6f6c;
  --shadow: rgba(0, 0, 0, 0.45);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  width: 100%;
  min-height: 100vh;
  font-family: Inter, "Segoe UI", sans-serif;
  background: radial-gradient(circle at top, rgba(92, 199, 255, 0.18), transparent 30%),
    linear-gradient(180deg, var(--bg-1), var(--bg-2));
  color: var(--text);
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.app-shell {
  width: min(1400px, 100%);
  min-height: 780px;
  display: grid;
  grid-template-columns: minmax(260px, 340px) minmax(0, 1fr);
  gap: 20px;
  padding: 18px;
  background: rgba(10, 17, 25, 0.45);
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 26px;
  box-shadow: 0 30px 60px var(--shadow);
  backdrop-filter: blur(8px);
}

.hud-panel {
  background: var(--panel);
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 22px;
  padding: 22px 18px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.brand-wrap h1 {
  margin: 4px 0 0;
  font-size: clamp(2rem, 2vw, 2.6rem);
  line-height: 1.05;
}

.eyebrow {
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--accent-2);
  font-weight: 700;
  font-size: 0.68rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.stat-box, .goal-panel, .mission-box, .legend {
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 16px;
}

.stat-box {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-box span {
  color: var(--muted);
  font-size: 0.76rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.stat-box strong {
  font-size: clamp(1.5rem, 2vw, 2rem);
}

.goal-panel {
  padding: 12px 14px;
}

.goal-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-size: 0.82rem;
}

.goal-row strong {
  color: var(--text);
}

.meter {
  margin-top: 10px;
  height: 12px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(148, 163, 184, 0.18);
}

.meter-fill {
  width: 0%;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2), var(--accent-3));
  box-shadow: 0 0 18px rgba(123, 220, 181, 0.5);
  transition: width 0.2s ease;
}

.controls {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

button {
  appearance: none;
  border: none;
  border-radius: 12px;
  background: linear-gradient(180deg, #1f7ae0 0%, #1a5dcc 100%);
  color: white;
  font-weight: 700;
  padding: 12px 14px;
  cursor: pointer;
  transition: transform 0.12s ease, filter 0.12s ease;
}

button:hover {
  filter: brightness(1.08);
}

button:active {
  transform: translateY(1px);
}

button:last-child {
  background: linear-gradient(180deg, #a977f5 0%, #8657d6 100%);
}

.mission-box, .legend {
  padding: 14px 16px;
}

.mission-box h2, .legend h2 {
  margin: 0 0 8px;
  font-size: 0.98rem;
  color: var(--accent-3);
}

.mission-box p {
  margin: 0;
  color: var(--text);
  line-height: 1.5;
}

.legend ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.legend li {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-size: 0.9rem;
}

.legend strong {
  color: var(--text);
  font-weight: 600;
}

.board-panel {
  background: linear-gradient(180deg, rgba(17, 37, 54, 0.8), rgba(17, 37, 54, 0.96));
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 22px;
  padding: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 720px;
}

canvas {
  width: min(100%, 980px);
  height: auto;
  display: block;
  border-radius: 20px;
  background: linear-gradient(180deg, #2d4d69 0%, #1d3549 100%);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08), 0 20px 30px rgba(0, 0, 0, 0.28);
}

@media (max-width: 980px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .board-panel {
    min-height: 560px;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const scoreValue = document.getElementById('scoreValue');
const lineValue = document.getElementById('lineValue');
const levelValue = document.getElementById('levelValue');
const speedValue = document.getElementById('speedValue');
const goalText = document.getElementById('goalText');
const goalFill = document.getElementById('goalFill');
const statusText = document.getElementById('statusText');
const restartBtn = document.getElementById('restartBtn');
const pauseBtn = document.getElementById('pauseBtn');

const BOARD_W = 10;
const BOARD_H = 18;
const BLOCK_SIZE = 32;
const GOAL_TARGET = 110;
const MAX_PX = 320;

const COLORS = {
  I: '#5cc7ff',
  O: '#f7d66b',
  T: '#d290ff',
  S: '#7bdcb5',
  Z: '#ef6f6c',
  J: '#7aa2ff',
  L: '#ffb857',
  wall: '#557e9b',
  floor: '#9fd5e9',
  grass: '#65d26d',
  dirt: '#a47546',
  wood: '#d89a5f',
  roof: '#d76f6a',
  glass: '#9dd9ff'
};

const SHAPES = {
  I: [[1, 1, 1, 1]],
  O: [[1, 1], [1, 1]],
  T: [[0, 1, 0], [1, 1, 1]],
  S: [[0, 1, 1], [1, 1, 0]],
  Z: [[1, 1, 0], [0, 1, 1]],
  J: [[1, 0, 0], [1, 1, 1]],
  L: [[0, 0, 1], [1, 1, 1]]
};

const pieceTypes = Object.keys(SHAPES);

function cloneMatrix(matrix) {
  return matrix.map((row) => row.slice());
}

function rotateMatrix(matrix) {
  const rows = matrix.length;
  const cols = matrix[0].length;
  const result = Array.from({ length: cols }, () => Array(rows).fill(0));

  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      result[x][rows - 1 - y] = matrix[y][x];
    }
  }

  return result;
}

function createBoard() {
  return Array.from({ length: BOARD_H }, () => Array(BOARD_W).fill(null));
}

function randomPiece() {
  const type = pieceTypes[Math.floor(Math.random() * pieceTypes.length)];
  const matrix = cloneMatrix(SHAPES[type]);
  return {
    type,
    matrix,
    x: Math.floor((BOARD_W - matrix[0].length) / 2),
    y: -1,
    color: COLORS[type]
  };
}

let board = createBoard();
let currentPiece = null;
let nextPiece = null;
let score = 0;
let lines = 0;
let level = 1;
let dropInterval = 800;
let lastTime = 0;
let accumulator = 0;
let paused = false;
let gameOver = false;
let goalValue = 0;
let houseBuilt = 0;
let tickFrame = 0;
let worldRotation = 0;

function readOnlyBoard() {
  return board.map((row) => row.slice());
}

function mergePiece() {
  if (!currentPiece) return;

  for (let y = 0; y < currentPiece.matrix.length; y++) {
    for (let x = 0; x < currentPiece.matrix[y].length; x++) {
      if (!currentPiece.matrix[y][x]) continue;
      const px = currentPiece.x + x;
      const py = currentPiece.y + y;
      if (py >= 0) {
        board[py][px] = currentPiece.type;
      }
    }
  }

  const cleared = clearLines();
  score += cleared * 40 * level;
  lines += cleared;
  level = 1 + Math.floor(lines / 10);
  dropInterval = Math.max(140, 800 - (level - 1) * 70);

  if (goalValue > GOAL_TARGET) {
    goalValue = GOAL_TARGET;
  }

  spawnPiece();
}

function clearLines() {
  let total = 0;
  for (let y = BOARD_H - 1; y >= 0; y--) {
    if (board[y].every(Boolean)) {
      board.splice(y, 1);
      board.unshift(Array(BOARD_W).fill(null));
      total++;
      y++;
    }
  }
  return total;
}

function collides(piece, offsetX = 0, offsetY = 0, nextMatrix = piece.matrix) {
  for (let y = 0; y < nextMatrix.length; y++) {
    for (let x = 0; x < nextMatrix[y].length; x++) {
      if (!nextMatrix[y][x]) continue;
      const bx = piece.x + x + offsetX;
      const by = piece.y + y + offsetY;
      if (bx < 0 || bx >= BOARD_W || by >= BOARD_H) return true;
      if (by >= 0 && board[by][bx]) return true;
    }
  }
  return false;
}

function spawnPiece() {
  if (!nextPiece) {
    nextPiece = randomPiece();
  }

  currentPiece = nextPiece;
  currentPiece.x = Math.floor((BOARD_W - currentPiece.matrix[0].length) / 2);
  currentPiece.y = -1;
  currentPiece.color = COLORS[currentPiece.type];
  nextPiece = randomPiece();

  if (collides(currentPiece, 0, 0, currentPiece.matrix)) {
    gameOver = true;
    paused = true;
    statusText.textContent = 'The build collapsed. Press restart to start a fresh Minecraft-inspired house.';
  }
}

function movePiece(dx, dy) {
  if (!currentPiece || paused || gameOver) return;
  if (!collides(currentPiece, dx, dy, currentPiece.matrix)) {
    currentPiece.x += dx;
    currentPiece.y += dy;
    return true;
  }
  return false;
}

function rotateCurrentPiece(direction) {
  if (!currentPiece || paused || gameOver) return;
  const rotated = rotateMatrix(currentPiece.matrix);
  if (direction < 0) {
    const temp = rotateMatrix(rotated);
    const temp2 = rotateMatrix(temp);
    const final = rotateMatrix(temp2);
    if (final.length === rotated.length && final[0].length === rotated[0].length) {
      currentPiece.matrix = final;
    }
    return;
  }

  const kicks = [0, -1, 1, -2, 2];
  for (const kick of kicks) {
    if (!collides(currentPiece, kick, 0, rotated)) {
      currentPiece.matrix = rotated;
      currentPiece.x += kick;
      return;
    }
  }
}

function softDrop() {
  if (!movePiece(0, 1)) {
    mergePiece();
  }
}

function hardDrop() {
  if (!currentPiece || paused || gameOver) return;
  let dropped = 0;
  while (!collides(currentPiece, 0, 1, currentPiece.matrix)) {
    currentPiece.y += 1;
    dropped += 1;
  }
  score += dropped * 2;
  mergePiece();
}

function computeHouseScore() {
  let filled = 0;
  for (let y = 0; y < BOARD_H; y++) {
    for (let x = 0; x < BOARD_W; x++) {
      if (board[y][x]) filled += 1;
    }
  }
  return Math.min(110, Math.floor(filled / 10));
}

function updateHud() {
  scoreValue.textContent = String(score);
  lineValue.textContent = String(lines);
  levelValue.textContent = String(level);
  speedValue.textContent = `${(800 / dropInterval).toFixed(1)}x`;

  goalValue = computeHouseScore();
  goalText.textContent = `${goalValue} / ${GOAL_TARGET}`;
  goalFill.style.width = `${(goalValue / GOAL_TARGET) * 100}%`;

  if (goalValue >= GOAL_TARGET) {
    statusText.textContent = 'House complete! The cozy cabin is fully built. Press restart for another round.';
    gameOver = true;
    paused = true;
  }
}

function resetGame() {
  board = createBoard();
  currentPiece = null;
  nextPiece = null;
  score = 0;
  lines = 0;
  level = 1;
  dropInterval = 800;
  lastTime = 0;
  accumulator = 0;
  paused = false;
  gameOver = false;
  goalValue = 0;
  houseBuilt = 0;
  tickFrame = 0;
  statusText.textContent = 'Stack the falling blocks. Fill the layers to finish the cozy Minecraft-style house.';
  spawnPiece();
  updateHud();
}

function clampRange(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function drawBlock(x, y, width, height, color, textured = false) {
  const px = x * width;
  const py = y * height;

  ctx.fillStyle = color;
  ctx.fillRect(px, py, width, height);

  if (textured) {
    ctx.strokeStyle = 'rgba(255,255,255,0.22)';
    ctx.strokeRect(px + 1, py + 1, width - 2, height - 2);
    ctx.fillStyle = 'rgba(255,255,255,0.18)';
    ctx.fillRect(px + 2, py + 2, width / 3, height / 3);
  } else {
    ctx.fillStyle = 'rgba(255,255,255,0.18)';
    ctx.fillRect(px + 2, py + 2, width - 4, 4);
    ctx.fillStyle = 'rgba(0,0,0,0.16)';
    ctx.fillRect(px + 3, py + height - 6, width - 6, 4);
  }
}

function drawBoard() {
  const boardLeft = 90;
  const boardTop = 40;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#1d384d';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#7ec6ff');
  sky.addColorStop(1, '#d7efff');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const sun = ctx.createRadialGradient(760, 120, 20, 760, 120, 110);
  sun.addColorStop(0, 'rgba(255,255,255,0.9)');
  sun.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = sun;
  ctx.fillRect(660, 20, 200, 200);

  ctx.fillStyle = '#87d975';
  ctx.fillRect(0, 620, canvas.width, 100);

  ctx.fillStyle = '#7a5130';
  ctx.fillRect(0, 580, canvas.width, 40);

  const houseX = 620;
  const houseY = 430;
  const baseW = 170;
  const baseH = 120;

  ctx.fillStyle = '#7c4f2b';
  ctx.fillRect(houseX, houseY + 70, baseW, 40);

  ctx.fillStyle = '#a2e0ff';
  ctx.fillRect(houseX + 22, houseY + 62, 126, 74);

  ctx.fillStyle = '#dca25d';
  ctx.fillRect(houseX + 38, houseY + 146, 28, 50);
  ctx.fillRect(houseX + 104, houseY + 146, 28, 50);

  ctx.fillStyle = '#e2c296';
  ctx.fillRect(houseX + 22, houseY + 40, 126, 18);
  ctx.fillStyle = '#d76f6a';
  ctx.beginPath();
  ctx.moveTo(houseX + 8, houseY + 62);
  ctx.lineTo(houseX + baseW / 2, houseY + 15);
  ctx.lineTo(houseX + baseW - 8, houseY + 62);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#8ecf8e';
  ctx.fillRect(houseX + 26, houseY + 82, 18, 18);
  ctx.fillStyle = '#9ad4ff';
  ctx.fillRect(houseX + 70, houseY + 84, 18, 18);
  ctx.fillStyle = '#8ecf8e';
  ctx.fillRect(houseX + 114, houseY + 82, 18, 18);

  const boardWidth = BOARD_W * BLOCK_SIZE;
  const boardHeight = BOARD_H * BLOCK_SIZE;
  const x0 = boardLeft;
  const y0 = boardTop;

  ctx.strokeStyle = 'rgba(240, 248, 255, 0.22)';
  ctx.lineWidth = 2;
  ctx.strokeRect(x0 - 10, y0 - 10, boardWidth + 20, boardHeight + 20);

  ctx.fillStyle = 'rgba(255,255,255,0.08)';
  ctx.fillRect(x0, y0, boardWidth, boardHeight);

  for (let y = 0; y < BOARD_H; y++) {
    for (let x = 0; x < BOARD_W; x++) {
      const block = board[y][x];
      if (!block) continue;
      const blockColor = {
        I: '#5cc7ff',
        O: '#f7d66b',
        T: '#d290ff',
        S: '#7bdcb5',
        Z: '#ef6f6c',
        J: '#7aa2ff',
        L: '#ffb857'
      }[block] || '#ffffff';
      drawBlock(x0 / BLOCK_SIZE + x, y0 / BLOCK_SIZE + y, BLOCK_SIZE, BLOCK_SIZE, blockColor, true);
    }
  }

  if (!currentPiece) return;

  for (let y = 0; y < currentPiece.matrix.length; y++) {
    for (let x = 0; x < currentPiece.matrix[y].length; x++) {
      if (!currentPiece.matrix[y][x]) continue;
      const px = currentPiece.x + x;
      const py = currentPiece.y + y;
      if (py < 0) continue;
      drawBlock(x0 / BLOCK_SIZE + px, y0 / BLOCK_SIZE + py, BLOCK_SIZE, BLOCK_SIZE, currentPiece.color, true);
    }
  }

  ctx.strokeStyle = 'rgba(255,255,255,0.33)';
  ctx.lineWidth = 2;
  ctx.strokeRect(x0 - 8, y0 - 8, boardWidth + 16, boardHeight + 16);
}

function update(timestamp) {
  if (!lastTime) lastTime = timestamp;
  const delta = timestamp - lastTime;
  lastTime = timestamp;

  if (!paused && !gameOver) {
    accumulator += delta;
    if (accumulator >= dropInterval) {
      accumulator = 0;
      softDrop();
      updateHud();
    }
  }

  drawBoard();
  requestAnimationFrame(update);
}

function keyHandler(event) {
  if (event.repeat) return;
  const key = event.key.toLowerCase();

  if (key === 'p') {
    paused = !paused;
    statusText.textContent = paused ? 'Paused. Build with care.' : 'Back to work on the structure.';
    return;
  }

  if (gameOver) {
    if (key === 'r') resetGame();
    return;
  }

  if (paused) return;

  if (key === 'arrowleft' || key === 'a') movePiece(-1, 0);
  if (key === 'arrowright' || key === 'd') movePiece(1, 0);
  if (key === 'arrowdown' || key === 's') softDrop();
  if (key === ' ' || key === 'spacebar') hardDrop();
  if (key === 'q') rotateCurrentPiece(-1);
  if (key === 'e') rotateCurrentPiece(1);
  if (key === 'w') movePiece(0, -1);
  if (key === 'r') resetGame();

  updateHud();
}

window.addEventListener('keydown', keyHandler);
restartBtn.addEventListener('click', resetGame);
pauseBtn.addEventListener('click', () => {
  if (gameOver) return;
  paused = !paused;
  statusText.textContent = paused ? 'Paused. Build with care.' : 'Back to work on the structure.';
});

resetGame();
requestAnimationFrame(update);

