24:   Z: '#ef6f6c', J: '#7aa2ff', L: '#ffb857'
25: };
26: const SHAPES = {
27:   I: [[1, 1, 1, 1]],
28:   O: [[1, 1], [1, 1]],
29:   T: [[0, 1, 0], [1, 1, 1]],
30:   S: [[0, 1, 1], [1, 1, 0]],
31:   Z: [[1, 1, 0], [0, 1, 1]],
32:   J: [[1, 0, 0], [1, 1, 1]],
33:   L: [[0, 0, 1], [1, 1, 1]]
34: };
35: const TYPES = Object.keys(SHAPES);
36: const SPACE_SHAPES = [
37:   [{ x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }, { x: 0, y: 1, z: 0 }, { x: 0, y: 0, z: 1 }],
38:   [{ x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }, { x: 1, y: 1, z: 0 }, { x: 1, y: 1, z: 1 }],
39:   [{ x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }, { x: 0, y: 0, z: 1 }, { x: 0, y: 1, z: 1 }]
40: ];
