42: function emptyBoard() {
43:   return Array.from({ length: BOARD_H }, () =>
44:     Array.from({ length: BOARD_D }, () => Array(BOARD_W).fill(null))
45:   );
46: }
47: function fromMatrix(matrix) {
48:   const cells = [];
49:   matrix.forEach((row, r) => row.forEach((filled, x) => {
50:     if (filled) cells.push({ x, y: matrix.length - 1 - r, z: 0 });
51:   }));
52:   return cells;
53: }
54: function normalize(cells) {
55:   const minX = Math.min(...cells.map((c) => c.x));
56:   const minY = Math.min(...cells.map((c) => c.y));
57:   const minZ = Math.min(...cells.map((c) => c.z));
58:   return cells.map((c) => ({ x: c.x - minX, y: c.y - minY, z: c.z - minZ }));
59: }
60: function makePiece(type) {
61:   // Mix in true 3-axis polycubes so some pieces occupy multiple depth layers.
62:   const cells = Math.random() < 0.3
63:     ? SPACE_SHAPES[Math.floor(Math.random() * SPACE_SHAPES.length)].map((cell) => ({ ...cell }))
64:     : fromMatrix(SHAPES[type]);
65:   return {
66:     type, cells, color: COLORS[type],
67:     x: Math.floor((BOARD_W - (Math.max(...cells.map((c) => c.x)) + 1)) / 2),
68:     y: BOARD_H - (Math.max(...cells.map((c) => c.y)) + 1),
69:     z: Math.floor((BOARD_D - 1) / 2)
70:   };
71: }
72: function randomType() { return TYPES[Math.floor(Math.random() * TYPES.length)]; }
73: 
74: let board = emptyBoard();
75: let current = null;
76: let nextType = randomType();
77: let score = 0;
78: let lines = 0;
79: let level = 1;
