87: function collides(piece, dx = 0, dy = 0, dz = 0, cells = piece.cells) {
88:   return cells.some((cell) => {
89:     const x = piece.x + cell.x + dx;
90:     const y = piece.y + cell.y + dy;
91:     const z = piece.z + cell.z + dz;
92:     if (x < 0 || x >= BOARD_W || z < 0 || z >= BOARD_D || y < 0) return true;
93:     return y < BOARD_H && Boolean(board[y][z][x]);
94:   });
95: }
96: function spawnPiece() {
97:   current = makePiece(nextType);
98:   nextType = randomType();
99:   if (collides(current)) endGame('The voxel tower reached the top. Press restart to build again.');
100: }
101: function endGame(message) {
102:   gameOver = true;
103:   paused = true;
104:   statusText.textContent = message;
105: }
106: function clearLayers() {
107:   let cleared = 0;
108:   for (let y = 0; y < BOARD_H; y++) {
109:     if (board[y].every((layer) => layer.every(Boolean))) {
110:       board.splice(y, 1);
111:       board.push(Array.from({ length: BOARD_D }, () => Array(BOARD_W).fill(null)));
112:       cleared++;
113:       y--;
114:     }
115:   }
116:   return cleared;
117: }
118: function lockPiece() {
119:   if (!current) return;
120:   for (const cell of current.cells) {
121:     const x = current.x + cell.x;
122:     const y = current.y + cell.y;
123:     const z = current.z + cell.z;
124:     if (y >= BOARD_H) {
125:       endGame('The voxel tower reached the top. Press restart to build again.');
126:       return;
127:     }
128:     board[y][z][x] = current.type;
129:     placedBlocks++;
130:   }
131:   const cleared = clearLayers();
132:   score += cleared * 100 * level;
133:   lines += cleared;
134:   level = 1 + Math.floor(lines / 4);
135:   dropInterval = Math.max(130, 800 - (level - 1) * 65);
136:   updateHud();
137:   if (placedBlocks >= GOAL_TARGET) {
138:     endGame('House complete! Your voxel cabin is ready. Press restart to build another.');
139:     return;
140:   }
141:   spawnPiece();
142: }
143: function move(dx, dy, dz) {
144:   if (!current || paused || gameOver) return false;
145:   if (collides(current, dx, dy, dz)) return false;
146:   current.x += dx;
147:   current.y += dy;
148:   current.z += dz;
149:   return true;
150: }
151: function dropOne() {
152:   if (!move(0, -1, 0)) lockPiece();
153: }
154: function hardDrop() {
155:   if (!current || paused || gameOver) return;
156:   let distance = 0;
157:   while (!collides(current, 0, -1, 0)) {
158:     current.y--;
159:     distance++;
160:   }
161:   score += distance * 2;
162:   lockPiece();
163:   updateHud();
164: }
165: function rotate(axis, direction) {
166:   if (!current || paused || gameOver) return;
167:   const rotated = normalize(current.cells.map((c) => {
168:     if (axis === 'z') return direction > 0
169:       ? { x: c.y, y: -c.x, z: c.z }
170:       : { x: -c.y, y: c.x, z: c.z };
171:     return direction > 0
172:       ? { x: c.z, y: c.y, z: -c.x }
173:       : { x: -c.z, y: c.y, z: c.x };
174:   }));
175:   // Small wall kicks keep rotations usable at the edges of the 3D well.
176:   const kicks = axis === 'z'
177:     ? [[0, 0], [-1, 0], [1, 0], [-2, 0], [2, 0], [0, 1]]
178:     : [[0, 0], [-1, 0], [1, 0], [0, -1], [0, 1]];
179:   for (const [dx, dz] of kicks) {
180:     if (!collides(current, dx, 0, dz, rotated)) {
181:       current.cells = rotated;
182:       current.x += dx;
183:       current.z += dz;
184:       return;
185:     }
186:   }
187: }
188: function resetGame() {
189:   board = emptyBoard();
190:   current = null;
191:   nextType = randomType();
192:   score = 0;
193:   lines = 0;
194:   level = 1;
195:   dropInterval = 800;
196:   lastTime = 0;
197:   accumulator = 0;
198:   paused = false;
199:   gameOver = false;
200:   placedBlocks = 0;
201:   statusText.textContent = 'Place blocks in all three dimensions. Every voxel helps build your cabin.';
202:   spawnPiece();
203:   updateHud();
204: }
205: function updateHud() {
206:   scoreValue.textContent = String(score);
207:   lineValue.textContent = String(lines);
208:   levelValue.textContent = String(level);
209:   speedValue.textContent = `${(800 / dropInterval).toFixed(1)}x`;
210:   const progress = Math.min(GOAL_TARGET, placedBlocks);
211:   goalText.textContent = `${progress} / ${GOAL_TARGET}`;
212:   goalFill.style.width = `${progress}%`;
