215: // Isometric projection shared by the well, falling pieces, and the growing house.
216: const originX = 380;
217: const floorY = 610;
218: function project(x, y, z, size = 1) {
219:   return {
220:     x: originX + (x - z) * CELL_W * size / 2,
221:     y: floorY - y * CELL_V * size + (x + z) * CELL_H * size / 2
222:   };
223: }
224: function polygon(points, fill, stroke = 'rgba(10,25,35,.42)') {
225:   ctx.beginPath();
226:   ctx.moveTo(points[0].x, points[0].y);
227:   for (let i = 1; i < points.length; i++) ctx.lineTo(points[i].x, points[i].y);
228:   ctx.closePath();
229:   ctx.fillStyle = fill;
230:   ctx.fill();
231:   if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1; ctx.stroke(); }
232: }
233: function drawCube(x, y, z, color, size = 1, alpha = 1) {
234:   // Grid coordinates mark the cube's bottom; its top face is one voxel higher.
235:   const p = project(x, y + 1, z, size);
236:   const w = CELL_W * size / 2;
237:   const h = CELL_H * size / 2;
238:   const v = CELL_V * size;
239:   ctx.save();
240:   ctx.globalAlpha = alpha;
241:   // Visible left and right walls, then the top face.
242:   polygon([{ x: p.x, y: p.y }, { x: p.x, y: p.y + v }, { x: p.x - w, y: p.y + v + h }, { x: p.x - w, y: p.y + h }], shade(color, -28));
243:   polygon([{ x: p.x, y: p.y }, { x: p.x, y: p.y + v }, { x: p.x + w, y: p.y + v + h }, { x: p.x + w, y: p.y + h }], shade(color, -12));
244:   polygon([{ x: p.x, y: p.y }, { x: p.x + w, y: p.y + h }, { x: p.x, y: p.y + 2 * h }, { x: p.x - w, y: p.y + h }], shade(color, 18));
