246: }
247: function shade(hex, amount) {
248:   const n = parseInt(hex.slice(1), 16);
249:   const r = Math.max(0, Math.min(255, (n >> 16) + amount));
250:   const g = Math.max(0, Math.min(255, ((n >> 8) & 255) + amount));
251:   const b = Math.max(0, Math.min(255, (n & 255) + amount));
252:   return `rgb(${r},${g},${b})`;
253: }
254: function drawBackdrop() {
255:   const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
256:   sky.addColorStop(0, '#78bfe8');
257:   sky.addColorStop(0.65, '#d7efff');
258:   sky.addColorStop(1, '#a7d68c');
259:   ctx.fillStyle = sky;
260:   ctx.fillRect(0, 0, canvas.width, canvas.height);
261:   ctx.fillStyle = 'rgba(255,255,255,.55)';
262:   ctx.beginPath(); ctx.arc(790, 105, 46, 0, Math.PI * 2); ctx.fill();
263:   // Distant blocky hills.
264:   ctx.fillStyle = '#8bc98e';
265:   ctx.beginPath(); ctx.moveTo(0, 385); ctx.lineTo(120, 280); ctx.lineTo(235, 385); ctx.lineTo(350, 300); ctx.lineTo(500, 400); ctx.lineTo(650, 290); ctx.lineTo(820, 390); ctx.lineTo(960, 310); ctx.lineTo(960, 720); ctx.lineTo(0, 720); ctx.fill();
