269: function drawWell() {
270:   // Isometric floor and faint cell grid.
271:   const a = project(0, 0, 0), b = project(BOARD_W, 0, 0);
272:   const c = project(BOARD_W, 0, BOARD_D), d = project(0, 0, BOARD_D);
273:   polygon([a, b, c, d], 'rgba(25,57,65,.58)', 'rgba(255,255,255,.55)');
274:   ctx.strokeStyle = 'rgba(236,250,255,.24)';
275:   ctx.lineWidth = 1;
276:   for (let x = 0; x <= BOARD_W; x++) {
277:     const p1 = project(x, 0, 0), p2 = project(x, 0, BOARD_D);
278:     ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
279:   }
280:   for (let z = 0; z <= BOARD_D; z++) {
281:     const p1 = project(0, 0, z), p2 = project(BOARD_W, 0, z);
282:     ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
283:   }
284:   // Back and side guides outline the height of the volume.
285:   const top = project(0, BOARD_H, BOARD_D);
286:   const rightTop = project(BOARD_W, BOARD_H, BOARD_D);
287:   const farTop = project(BOARD_W, BOARD_H, 0);
288:   ctx.strokeStyle = 'rgba(255,255,255,.35)';
289:   ctx.setLineDash([5, 6]);
290:   [[d, top], [c, rightTop], [b, farTop], [top, rightTop], [rightTop, farTop]].forEach(([p1, p2]) => {
291:     ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
292:   });
293:   ctx.setLineDash([]);
294:   // Draw far-to-near so the front voxels naturally overlay the back ones.
295:   for (let y = 0; y < BOARD_H; y++) {
296:     for (let sum = 0; sum <= BOARD_W + BOARD_D - 2; sum++) {
297:       for (let z = 0; z < BOARD_D; z++) {
298:         const x = sum - z;
299:         if (x < 0 || x >= BOARD_W || !board[y][z][x]) continue;
300:         drawCube(x, y, z, COLORS[board[y][z][x]]);
301:       }
302:     }
303:   }
304:   if (current) current.cells.forEach((cell) => {
305:     const x = current.x + cell.x, y = current.y + cell.y, z = current.z + cell.z;
306:     if (y >= 0 && y < BOARD_H) drawCube(x, y, z, current.color, 1, .98);
307:   });
308: }
309: function drawHouse() {
310:   const x = 710, z = 0, size = 1.08;
311:   const progress = Math.min(1, placedBlocks / GOAL_TARGET);
312:   ctx.fillStyle = 'rgba(16,54,54,.16)';
313:   ctx.beginPath(); ctx.ellipse(760, 592, 145, 38, 0, 0, Math.PI * 2); ctx.fill();
314:   // Foundation and timber frame appear first.
315:   const foundation = progress > 0.02;
316:   const walls = Math.floor(Math.max(0, progress - .12) * 7);
