321:   }
322:   for (let levelY = 0; levelY < Math.min(4, walls); levelY++) {
323:     for (let dx = 0; dx < 4; dx++) {
324:       for (const dz of [0, 2]) drawCube(x + dx, levelY + 1, z + dz, '#d6a467', size);
325:     }
326:     for (const dz of [0, 1, 2]) {
327:       for (const dx of [0, 3]) drawCube(x + dx, levelY + 1, z + dz, '#c58a51', size);
328:     }
329:   }
330:   if (progress > .42) {
