332:     drawCube(x + 2, 1, z, '#75c9e8', size, .95);
333:   }
334:   if (progress > .56) {
335:     drawCube(x + 1, 1, z + 2, '#75c9e8', size, .95);
336:     drawCube(x + 2, 1, z + 2, '#75c9e8', size, .95);
337:   }
338:   if (progress > .62) drawCube(x + 2, 1, z + 1, '#805332', size);
339:   if (roof) {
340:     for (let dx = -1; dx < 5; dx++) {
341:       for (let dz = -1; dz < 4; dz++) {
342:         drawCube(x + dx, 5, z + dz, '#bd5149', size);
343:       }
344:     }
345:   }
346:   ctx.fillStyle = '#234a42';
347:   ctx.font = '700 19px Inter, sans-serif';
348:   ctx.textAlign = 'center';
349:   ctx.fillText('YOUR VOXEL CABIN', 760, 220);
350:   ctx.font = '600 13px Inter, sans-serif';
351:   ctx.fillStyle = '#285a50';
352:   ctx.fillText(`${Math.round(progress * 100)}% BUILT`, 760, 242);
